-- MODEL-001B2b2d: typed closed-region save.
create function graftvision_private.save_model_region(p_session_id uuid,p_provider_identity_id uuid,p_annotation_package_id uuid,p_region_code text,p_points jsonb,p_closed boolean,p_expected_package_revision integer,p_expected_pointer_revision integer,p_idempotency_key uuid)
returns table(region_version_id uuid,package_revision integer,pointer_revision integer,is_new boolean)
language plpgsql security definer set search_path='' as $$ declare p public.model_annotation_package%rowtype; m public.scalp_model_package%rowtype; c record; q public.model_annotation_region_current%rowtype; e public.model_annotation_idempotency%rowtype; v uuid; h text; n integer; hp boolean:=false; begin
 
