 perform set_config('graftvision.scan_controlled','on',true); insert into public.model_annotation_region_version(annotation_package_id,clinic_id,patient_id,consultation_id,model_package_id,reconstruction_output_manifest_id,model_artifact_id,geometry_revision,region_code,boundary_points,closed,revision,supersedes_region_id,created_by) values(p.id,p.clinic_id,p.patient_id,p.consultation_id,p.model_package_id,p.reconstruction_output_manifest_id,p.model_artifact_id,p.geometry_revision,p_region_code,p_points,true,p.revision+1,case when hp then q.current_version_id else null end,c.actor_id) returning id into v; insert into public.model_annotation_region_current(annotation_package_id,clinic_id,patient_id,consultation_id,model_package_id,reconstruction_output_manifest_id,model_artifact_id,geometry_revision,normalization_version,region_code,current_version_id,prior_version_id,revision,updated_by) values(p.id,p.clinic_id,p.patient_id,p.consultation_id,p.model_package_id,p.reconstruction_output_manifest_id,p.model_artifact_id,p.geometry_revision,p.normalization_version,p_region_code,v,case when hp then q.current_version_id else null end,1,c.actor_id) 
-- graftvision:dangerous-sql-approved task=MODEL-001
-- graftvision:dangerous-sql-reason Controlled row locks and revision updates serialize immutable Doctor annotation saves.
-- graftvision:corrective-plan Forward-fix through an additive migration; append-only annotation versions, pointers, events, and audit history remain preserved.
on conflict(annotation_package_id,region_code) do update set current_version_id=excluded.current_version_id,prior_version_id=model_annotation_region_current.current_version_id,revision=model_annotation_region_current.revision+1,updated_at=clock_timestamp(),updated_by=excluded.updated_by returning revision into pointer_revision; 
-- graftvision:dangerous-sql-approved task=MODEL-001
-- graftvision:dangerous-sql-reason Controlled row locks and revision updates serialize immutable Doctor annotation saves.
-- graftvision:corrective-plan Forward-fix through an additive migration; append-only annotation versions, pointers, events, and audit history remain preserved.
update public.model_annotation_package set revision=revision+1 where id=p.id returning revision into package_revision; insert into public.model_annotation_event(annotation_package_id,clinic_id,event_type,actor_platform_user_id,annotation_reference_id,annotation_code,revision) values(p.id,p.clinic_id,'region_saved',c.actor_id,v,p_region_code,package_revision); insert into public.audit_event(audit_scope,clinic_id,actor_platform_user_id,actor_type,action,resource_type,resource_id,outcome,request_id,source_application,metadata) values('clinic',p.clinic_id,c.actor_id,'user','model.region_saved','consultation',p.consultation_id,'success',p_idempotency_key,'web',jsonb_build_object('annotation_package_id',p.id,'model_package_id',p.model_package_id,'annotation_kind','region','annotation_code',p_region_code,'revision',package_revision,'package_state','draft','geometry_revision',p.geometry_revision)); insert into public.model_annotation_idempotency(clinic_id,actor_platform_user_id,request_family,idempotency_key,payload_hash,result_resource_id,result_status,result_revision) values(p.clinic_id,c.actor_id,'region',p_idempotency_key,h,v,'created',package_revision); return query select v,package_revision,pointer_revision,true; end; $$;
revoke all on function graftvision_private.save_model_region(uuid,uuid,uuid,text,jsonb,boolean,integer,integer,uuid) from public,anon,authenticated;
